CREATE TABLE carrier_scorecard_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name text NOT NULL,delivery_weight numeric(6,3) NOT NULL DEFAULT 30,cost_weight numeric(6,3) NOT NULL DEFAULT 25,quality_weight numeric(6,3) NOT NULL DEFAULT 20,invoice_weight numeric(6,3) NOT NULL DEFAULT 10,claims_weight numeric(6,3) NOT NULL DEFAULT 15,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),UNIQUE(company_id,name),CHECK(delivery_weight+cost_weight+quality_weight+invoice_weight+claims_weight=100));
CREATE TABLE carrier_performance_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,carrier_service_id uuid NOT NULL,on_time_delivery_target numeric(6,3) NOT NULL DEFAULT 95,max_failure_rate numeric(6,3) NOT NULL DEFAULT 2,max_cost_variance_percent numeric(8,3) NOT NULL DEFAULT 10,max_invoice_dispute_rate numeric(6,3) NOT NULL DEFAULT 3,min_claim_recovery_rate numeric(6,3) NOT NULL DEFAULT 80,effective_from date NOT NULL,effective_to date,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id),CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE carrier_performance_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,carrier_service_id uuid NOT NULL,warehouse_id uuid NOT NULL,period_start date NOT NULL,period_end date NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','in_review','accepted','requires_action','closed')),score numeric(7,3),review_note text,reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),UNIQUE(company_id,carrier_service_id,warehouse_id,period_start,period_end),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id),CHECK(period_end>=period_start));
CREATE TABLE carrier_corrective_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,review_id uuid NOT NULL REFERENCES carrier_performance_reviews(id) ON DELETE CASCADE,title text NOT NULL,description text NOT NULL,owner_id uuid REFERENCES users(id),due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','completed','cancelled')),completion_note text,completed_at timestamptz,completed_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id));
CREATE VIEW carrier_performance_scorecards WITH(security_invoker=true) AS WITH delivery AS(SELECT sh.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',sh.dispatched_at)::date period,count(*) shipments,100.0*count(*)FILTER(WHERE sh.delivery_status='delivered' AND(sh.expected_delivery_at IS NULL OR sh.delivered_at<=sh.expected_delivery_at))/nullif(count(*),0) on_time_delivery_rate,100.0*count(*)FILTER(WHERE sh.delivery_status IN('failed','returned'))/nullif(count(*),0) failure_rate FROM shipments sh JOIN sales_orders o ON o.id=sh.order_id WHERE sh.carrier_service_id IS NOT NULL GROUP BY sh.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',sh.dispatched_at)::date),cost AS(SELECT f.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',sh.dispatched_at)::date period,100.0*sum(coalesce(f.actual_amount,f.estimated_amount)-f.estimated_amount)/nullif(sum(f.estimated_amount),0) cost_variance_percent FROM shipment_freight_costs f JOIN shipments sh ON sh.id=f.shipment_id JOIN sales_orders o ON o.id=sh.order_id GROUP BY f.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',sh.dispatched_at)::date),invoice AS(SELECT l.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',i.invoice_date)::date period,100.0*count(*)FILTER(WHERE l.review_status='disputed')/nullif(count(*),0) invoice_dispute_rate FROM carrier_freight_invoice_lines l JOIN carrier_freight_invoices i ON i.id=l.invoice_id LEFT JOIN shipments sh ON sh.id=l.shipment_id LEFT JOIN sales_orders o ON o.id=sh.order_id WHERE sh.id IS NOT NULL GROUP BY l.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',i.invoice_date)::date),claims AS(SELECT d.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',d.created_at)::date period,count(*) claims,100.0*sum(coalesce(d.approved_amount,0))/nullif(sum(d.claimed_amount),0) claim_recovery_rate,100.0*count(*)/nullif(max(dl.shipments),0) quality_incident_rate FROM delivery_claims d JOIN shipments sh ON sh.id=d.shipment_id JOIN sales_orders o ON o.id=sh.order_id LEFT JOIN delivery dl ON dl.company_id=d.company_id AND dl.carrier_service_id=sh.carrier_service_id AND dl.warehouse_id=o.warehouse_id AND dl.period=date_trunc('month',d.created_at)::date GROUP BY d.company_id,sh.carrier_service_id,o.warehouse_id,date_trunc('month',d.created_at)::date) SELECT dl.company_id,dl.carrier_service_id,dl.warehouse_id,dl.period,dl.shipments,coalesce(dl.on_time_delivery_rate,0) on_time_delivery_rate,coalesce(dl.failure_rate,0) failure_rate,coalesce(c.cost_variance_percent,0) cost_variance_percent,coalesce(i.invoice_dispute_rate,0) invoice_dispute_rate,coalesce(cl.quality_incident_rate,0) quality_incident_rate,coalesce(cl.claim_recovery_rate,100) claim_recovery_rate,coalesce(t.on_time_delivery_target,95) on_time_delivery_target,coalesce(t.max_failure_rate,2) max_failure_rate,coalesce(t.max_cost_variance_percent,10) max_cost_variance_percent,coalesce(t.max_invoice_dispute_rate,3) max_invoice_dispute_rate,coalesce(t.min_claim_recovery_rate,80) min_claim_recovery_rate,((coalesce(dl.on_time_delivery_rate,0)<coalesce(t.on_time_delivery_target,95))::int+(coalesce(dl.failure_rate,0)>coalesce(t.max_failure_rate,2))::int+(abs(coalesce(c.cost_variance_percent,0))>coalesce(t.max_cost_variance_percent,10))::int+(coalesce(i.invoice_dispute_rate,0)>coalesce(t.max_invoice_dispute_rate,3))::int+(coalesce(cl.claim_recovery_rate,100)<coalesce(t.min_claim_recovery_rate,80))::int) breach_count,greatest(0,least(100,(coalesce(dl.on_time_delivery_rate,0)*coalesce(cfg.delivery_weight,30)/100)+(greatest(0,100-abs(coalesce(c.cost_variance_percent,0)))*coalesce(cfg.cost_weight,25)/100)+(greatest(0,100-coalesce(cl.quality_incident_rate,0))*coalesce(cfg.quality_weight,20)/100)+(greatest(0,100-coalesce(i.invoice_dispute_rate,0))*coalesce(cfg.invoice_weight,10)/100)+(coalesce(cl.claim_recovery_rate,100)*coalesce(cfg.claims_weight,15)/100))) score FROM delivery dl LEFT JOIN cost c USING(company_id,carrier_service_id,warehouse_id,period) LEFT JOIN invoice i USING(company_id,carrier_service_id,warehouse_id,period) LEFT JOIN claims cl USING(company_id,carrier_service_id,warehouse_id,period) LEFT JOIN LATERAL(SELECT * FROM carrier_scorecard_configs x WHERE x.company_id=dl.company_id AND x.active ORDER BY x.created_at DESC LIMIT 1)cfg ON true LEFT JOIN LATERAL(SELECT * FROM carrier_performance_targets x WHERE x.company_id=dl.company_id AND x.carrier_service_id=dl.carrier_service_id AND x.effective_from<=dl.period AND(x.effective_to IS NULL OR x.effective_to>=dl.period) ORDER BY x.effective_from DESC LIMIT 1)t ON true;
ALTER TABLE carrier_scorecard_configs ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_scorecard_configs FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_performance_targets ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_performance_targets FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_performance_reviews ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_performance_reviews FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_corrective_actions ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_corrective_actions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_carrier_scorecard_configs ON carrier_scorecard_configs USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_performance_targets ON carrier_performance_targets USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_performance_reviews ON carrier_performance_reviews USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_corrective_actions ON carrier_corrective_actions USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_scorecard_configs,carrier_performance_targets,carrier_performance_reviews,carrier_corrective_actions TO stockflow_app;GRANT SELECT ON carrier_performance_scorecards TO stockflow_app;CREATE INDEX carrier_reviews_queue_idx ON carrier_performance_reviews(company_id,warehouse_id,status,period_end);CREATE INDEX carrier_actions_due_idx ON carrier_corrective_actions(company_id,status,due_at);
INSERT INTO carrier_scorecard_configs(company_id,name,created_by) SELECT c.id,'Default weighted score',m.user_id FROM companies c JOIN LATERAL(SELECT user_id FROM company_members WHERE company_id=c.id AND role='owner' ORDER BY user_id LIMIT 1)m ON true;
